-- =============================================================================
-- V1.57__seed_qa_books_textbook.sql
-- =============================================================================
-- 功能: 为 AI 客服学习知识库 (ai_cs_learned_kb) 填充"图书教材"一级分类
--       (books_textbook) 下 5 个二级分类的高价值 Q&A 种子数据。
--
-- 数据规模: 5 个二级分类 x 30 条 = 150 条 Q&A
--   1. books_textbook     - 教材教辅 (教材/教辅/课本/练习册/试卷/参考书)
--   2. books_novel        - 小说文学 (小说/文学/名著/散文/诗集/网络小说)
--   3. books_magazine     - 杂志期刊 (杂志/期刊/读者/意林/时尚/国家地理)
--   4. books_professional - 专业书籍 (专业/技术/编程/医学/法律/经管)
--   5. books_children     - 儿童读物 (绘本/童话/儿童/启蒙/拼音/故事)
--
-- Q&A 覆盖场景: 版本年份、是否有笔记、是否缺页、是否盗版、是否完整套装、
--               新旧程度、是否附赠光盘、议价、发货、退货等真实闲鱼图书买卖场景。
--
-- 幂等性说明: content_hash = MD5(question+answer), 唯一键 uk_learned_kb_hash
--             保证同一 (question, answer) 不会重复插入。
--
-- 依赖: ai_cs_kb_category 表中需已存在上述 5 个二级分类 code，且
--       parent_id 非空 (即挂载在 books_textbook 一级分类下)。
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 1. books_textbook - 教材教辅 (30 条)
-- ---------------------------------------------------------------------------
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.57', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'books_textbook' AS code, '这套人教版数学教材是几年级的？是最新版本吗？' AS question, '您好！这套是人教版小学数学五年级上册，2023年6月印刷最新版，封面有"教育部审定"标识。课本纸张洁白、印刷清晰，孩子用着不伤眼。我之前给自家孩子用，孩子已升六年级才转手，保存很新，内页无涂写折痕。教材每年版本变化不大，但新版会修订少量例题和插图，建议买最新版更稳妥。如需配套练习册可一并出，再优惠5元，包顺丰今天下午拍下当晚发出。有问题随时联系我哈！' AS answer, '教材,人教版,数学,版本' AS tags, '教材版本年份确认与配套推荐' AS source_summary, 88 AS score
  UNION ALL SELECT 'books_textbook', '书里有没有别人的笔记或涂画？孩子用介意。', '您放心，这本教材内页干净无任何笔记、涂画或折痕！孩子当时用铅笔做作业，已全部擦干净，几乎看不出痕迹。仅扉页有孩子小名，可撕掉或修正带盖一下。教材保存得好，孩子用起来心情也好，学习效率自然高。如收到不满意，7天内支持无理由退换，邮费我承担，尽管放心拍。包圆通快递，发货前再拍照确认品相，确保与描述一致，绝不让您吃亏。', '教材,笔记,品相,退货' AS tags, '教材笔记与涂画情况说明' AS source_summary, 90
  UNION ALL SELECT 'books_textbook', '这本书有没有缺页或撕掉的地方？', '亲，这本《高等数学》第七版上下册完整无缺页，我专门逐页翻检过，从目录到附录全部齐全。书本是我大学时用，毕业后一直放书柜保存，无水浸、无撕裂。仅外页边缘有轻微使用痕迹，不影响阅读。专业书缺一页都会影响学习连贯性，所以我很仔细检查过。可发顺丰到付，发货前再拍视频确认。如不放心可走验货签收，有问题直接拒收。诚心出，价格可小刀，期待成交！', '高数,缺页,完整,验货' AS tags, '教材完整性核查与验货说明' AS source_summary, 87
  UNION ALL SELECT 'books_textbook', '这套书是正版吗？闲鱼盗版太多担心买到。', '您火眼金睛！完全理解您的顾虑，闲鱼确实鱼龙混杂。这套《五三》是正版，出版社直发，封面有防伪激光标，纸张厚实、油墨清晰不晕染。可拍内页细节图给您看，正版书的色彩饱和度和印刷精度盗版根本做不出来。也可走验货签收，收到后比对正版特征再确认。支持7天无理由退换，假一赔三。如需发票可联系出版社补开。诚信经营，欢迎长期合作，后续有教辅需要随时找我！', '教辅,正版,防伪,验货' AS tags, '教辅正版验证与售后保障' AS source_summary, 92
  UNION ALL SELECT 'books_textbook', '这套《黄冈小状元》是完整套装吗？有没有缺本？', '您好！这是一年级到六年级全套12本，语文数学各6册，一本不缺，还有配套《作业本》和《试卷》各6本，共24本齐全套装。原价288元，我100元出，相当于3.5折，性价比超高。书本九成新，孩子已升初中，留着占地方。套装完整出更有价值，单买不划算。建议整套装齐给孩子，学习有连贯性。包中通快递，发货前清点核对再打包。如收到发现缺本，第一时间补发，绝不让您吃亏。', '教辅,套装,完整,黄冈' AS tags, '教辅套装完整性确认与补发承诺' AS source_summary, 89
  UNION ALL SELECT 'books_textbook', '这本《新华字典》第12版新旧程度怎么样？描述下品相。', '亲，这本《新华字典》第12版双色彩印本是9成新，封面塑封未拆，仅边角有轻微运输压痕。内页全新未翻阅，纸张洁白无任何痕迹。第12版是2020年最新修订版，新增800多个新词，比第11版更全面，孩子小学到初中都能用。原价32.9元，我20元出，比书店便宜近13元。书是朋友送的双份，自家已有才出。包顺丰，今天拍今天发，最快次日达。品相问题包退换，放心拍！', '字典,品相,新版,顺丰' AS tags, '字典品相与版本说明' AS source_summary, 86
  UNION ALL SELECT 'books_textbook', '教材有没有附赠光盘或答案？孩子需要核对。', '您好！这套人教版英语教材附赠的光盘和教师用书答案都在，光盘无划痕可正常读取，答案是单独成册的，方便孩子核对。光盘内容是课文录音和单词发音，对孩子听力和口语很有帮助。我整套装一起出，不拆卖，价格可小刀。如需发顺丰到付也可以。发货前会测试光盘读取正常再发，确保您收到能用。有任何问题随时联系，诚信出，期待成交，孩子学习有需要后续随时找我！', '教材,光盘,答案,配套' AS tags, '教材配套光盘答案完整性' AS source_summary, 88
  UNION ALL SELECT 'books_textbook', '这套2020年的教辅现在还能用吗？会不会过期？', '亲，您问得很专业！这套2020版《五三》数学虽然出版3年，但知识点和考点基本不变，完全能继续用。每年新版只是微调少量例题和年份标识，核心内容一致。教材教辅的"过期"主要是题库年份更新，但基础题型和解题方法是稳定的。如果您孩子是2024年中考，建议搭配一本最新模拟题即可。我这套价格只有新书3折，性价比极高。包中通，今天拍今天发，7天无理由退换，放心拍！', '教辅,过期,版本,性价比' AS tags, '教辅年份适用性说明' AS source_summary, 85
  UNION ALL SELECT 'books_textbook', '这套试卷有没有写过？答案还在吗？', '您好！这套《期末100分》试卷完全没写过，是孩子没用上的库存。答案册完整附赠，没有撕掉或涂改。试卷纸张洁白，印刷清晰，无任何折痕和水渍。原价45元，我15元出，3折都不到。试卷适合期末复习冲刺，搭配教材使用效果更好。如需多套可优惠，3套以上再减5元。包圆通，发货前会再检查一遍完整性。品相问题包退换，诚信出，期待成交，后续有学习资料需要随时找我！', '试卷,答案,空白,完整' AS tags, '试卷使用情况与答案完整性' AS source_summary, 87
  UNION ALL SELECT 'books_textbook', '这套教材是哪个出版社的？ISBN能发一下吗？', '亲，这套是人教版（人民教育出版社）2022年印刷，ISBN 978-7-107-35234-1，您可以通过ISBN在出版社官网或京东图书查证。人教版是全国统编教材，使用范围最广，版本最权威。书本保存9成新，无笔记无折痕。如需我拍版权页照片确认也可以。原价一套128元，我40元出，3折优惠。包顺丰，今天拍今天发。支持7天无理由退换，假一赔三，放心拍！', '教材,人教版,ISBN,正版' AS tags, '教材出版社与ISBN核验' AS source_summary, 91
  UNION ALL SELECT 'books_textbook', '书本有没有水浸或发霉？储存环境怎么样？', '您放心，书本一直存放在干燥书柜中，无水浸、无发霉、无异味。我家是北方干燥气候，藏书条件很好。书本边角无翘起，纸张无泛黄，整体品相9成新。发货前会用气泡膜加硬纸板加固包装，防水防潮。如收到发现水渍或霉斑，7天内包退换，邮费我承担。诚信出，期待成交！后续有教材教辅需要也可随时咨询，长期出学习资料。', '教材,储存,品相,防潮' AS tags, '教材储存环境与防潮包装' AS source_summary, 84
  UNION ALL SELECT 'books_textbook', '这套教辅支持拆卖吗？我只需要数学部分。', '亲，建议您整套装收下，拆卖后剩余不好出。不过如果您只要数学6册，我可以拆，价格60元（整套装100元）。但语文部分会再等买家，可能要一段时间。如果您急用，建议整套装收，语文部分可转赠朋友或挂二手。套装完整出对孩子学习更有价值，知识点衔接更顺畅。包中通，今天拍今天发。7天无理由退换，放心拍！', '教辅,拆卖,套装,数学' AS tags, '教辅拆卖建议与套装价值' AS source_summary, 82
  UNION ALL SELECT 'books_textbook', '这套书有几本？能发个清单和实物图吗？', '您好！这套《一遍过》小学语文数学共12本，每个年级2本（练习加测试）。我可以发实物清单和细节图，包括封面、扉页、内页样品、封底。书本9成新，孩子用过2本（已擦干净），其余10本全新未拆封。原价180元，我50元出，性价比超高。包圆通，发货前再拍照确认。品相问题包退换，诚信出！如需其他年级教辅也可咨询。', '教辅,清单,实物图,套装' AS tags, '教辅套装清单与实物图' AS source_summary, 86
  UNION ALL SELECT 'books_textbook', '这本书印刷清晰吗？有没有盗版的可能？', '亲，这本《教材全解》是陕西人民教育出版社正版，印刷清晰、色彩饱满、纸张厚实。盗版书的特征是纸张薄透、油墨晕染、色彩发灰，我可以拍内页细节图对比给您看。也可走验货签收，收到后比对正版特征再确认。支持7天无理由退换，假一赔三。原价29.8元，我10元出，比盗版还便宜，何必买盗版呢？诚信出，期待成交！', '教辅,正版,印刷,验货' AS tags, '教辅正版特征与验货说明' AS source_summary, 88
  UNION ALL SELECT 'books_textbook', '这套教材能再便宜点吗？诚心要。', '亲，价格已经很低了，原价128元的套装我40元出，3折都不到。如果您诚心要，可以再让2元，38元包邮，这是底价了。书本9成新，无笔记无折痕，品相没问题。如需配套练习册可一并出，再优惠5元。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。诚信出，期待长期合作，后续有需要随时联系！', '教材,议价,优惠,套装' AS tags, '教材议价底线与组合优惠' AS source_summary, 83
  UNION ALL SELECT 'books_textbook', '这本书是精装还是平装？有没有书盒？', '您好！这本《现代汉语词典》第7版是精装本，原配书盒完好，封面硬壳、烫金工艺，很有质感。词典是商务印书馆权威版本，收录词条6.9万条，是中学生和职场人士必备工具书。书本9成新，仅书脊有轻微使用痕迹，内页无任何标记。原价109元，我60元出，5.5折优惠。包顺丰，今天拍今天发。品相问题包退换，放心拍！', '词典,精装,书盒,品相' AS tags, '词典装帧与书盒完整性' AS source_summary, 89
  UNION ALL SELECT 'books_textbook', '这套书适合几年级用？内容难度怎么样？', '亲，这套《奥数教程》是小学3-4年级版，内容从基础到拔高，分30讲，每讲有例题加练习加测试。难度适中，适合有一定数学基础的孩子拓展思维。如果您孩子是3年级，建议从一年级版开始打基础；4年级可直接用这套。原价45元，我15元出，3折优惠。书本9成新，无笔记。包中通，今天拍今天发。有任何学习问题也可咨询，期待成交！', '教辅,奥数,年级,难度' AS tags, '教辅适用年级与难度说明' AS source_summary, 85
  UNION ALL SELECT 'books_textbook', '这套书有没有配套的音视频资源？', '您好！这套《新概念英语》教材附赠MP3光盘和在线学习卡，光盘内容是课文朗读和听力练习，学习卡可激活APP看视频课程。光盘无划痕，学习卡未激活，全套资源完整。原价89元，我30元出，3.4折优惠。书本9成新，无笔记无折痕。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。诚信出，期待成交，英语学习有需要后续随时找我！', '教材,英语,光盘,音视频' AS tags, '教材配套音视频资源说明' AS source_summary, 87
  UNION ALL SELECT 'books_textbook', '这套书有几成新？能详细描述下使用痕迹吗？', '亲，这套《教材全解》9成新，详细描述：封面无折痕无破损，仅边角有轻微磨损；扉页有孩子姓名（可撕掉）；内页无任何笔记涂画，纸张洁白无泛黄；封底完好无污渍。整体品相很好，不影响阅读和使用。发货前会再拍照确认。原价180元，我45元出，2.5折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。诚信出！', '教辅,品相,九成新,描述' AS tags, '教辅品相详细描述' AS source_summary, 86
  UNION ALL SELECT 'books_textbook', '这套书支持同城自提吗？我在北京。', '您好！我在北京海淀，支持同城自提，地点可约中关村或五道口地铁站附近。自提可再优惠5元，因为省了邮费。书本9成新，自提可当面验货，满意再付款，更放心。如需邮寄也可，包顺丰，今天发次日达。原价128元，我40元出，自提35元。7天无理由退换（自提取货后不支持退货，邮寄支持）。诚信出，期待成交！', '教材,同城,自提,北京' AS tags, '教材同城自提与优惠' AS source_summary, 84
  UNION ALL SELECT 'books_textbook', '这套书什么时候发货？多久能到？', '亲，今天下午4点前拍下，当天下午5点发顺丰，最快次日达；4点后拍下，次日上午发顺丰，2-3天到。偏远地区（新疆、西藏、青海）需加10元邮费，3-5天到。发货前会拍照确认品相，发货后会提供运单号，您可实时查询物流。如收到有品相问题，7天内包退换，邮费我承担。诚信出，期待成交，有任何物流问题随时联系！', '教材,发货,顺丰,物流' AS tags, '教材发货时效与物流查询' AS source_summary, 88
  UNION ALL SELECT 'books_textbook', '这套书有没有教师用书？孩子需要参考答案。', '您好！这套教材附赠教师用书1本，包含所有课文答案和教学要点，方便家长辅导或孩子自查。教师用书是单独成册，不影响孩子使用教材。原价128元，我45元出（含教材加教师用书加练习册），3.5折优惠。书本9成新，无笔记无折痕。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。诚信出，期待成交，孩子学习有需要后续随时找我！', '教材,教师用书,答案,套装' AS tags, '教材教师用书与答案配套' AS source_summary, 89
  UNION ALL SELECT 'books_textbook', '这套书是哪个年份印刷的？会不会太旧？', '亲，这套是2023年6月印刷的最新版，不是旧书。教材每年都会重印，版本内容基本稳定，年份主要是印刷批次。我这套是去年买的，孩子用了一年升入高年级才转手，保存很新。如需最新2024版可去书店买全新，价格高3倍。我这套3折出，内容一样，性价比更高。包顺丰，今天拍今天发。7天无理由退换，放心拍！', '教材,印刷年份,新版,性价比' AS tags, '教材印刷年份与版本说明' AS source_summary, 86
  UNION ALL SELECT 'books_textbook', '这套书有没有写过名字或盖章？', '您好！这套教材扉页有孩子姓名（铅笔写的，可擦掉），无盖章、无学校标识。内页无任何笔记涂画，纸张洁白。书本9成新，无折痕无水渍。发货前会擦掉姓名，再拍照确认。原价128元，我40元出，3折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。诚信出，期待成交，后续有教材需要也可咨询！', '教材,姓名,盖章,品相' AS tags, '教材姓名盖章情况说明' AS source_summary, 85
  UNION ALL SELECT 'books_textbook', '这套书有多本吗？想一次收齐给两个孩子用。', '亲，我手上有2套相同的教材，如果您一次收2套，可再优惠10元，2套共70元（单套40元）。书本都是9成新，品相一致，适合给两个孩子用。如需不同年级的教材，我也有其他年级库存，可一并出，价格更优惠。包顺丰，2套一起发，邮费我承担。7天无理由退换，品相问题包退换。诚信出，期待长期合作！', '教材,多套,优惠,批发' AS tags, '教材多套优惠与批发' AS source_summary, 83
  UNION ALL SELECT 'books_textbook', '这套书能退货吗？孩子用不上想退。', '您放心，支持7天无理由退换！您收到后让孩子先翻翻看是否合适，如不合适7天内可退，邮费我承担。但需保持书本原样，无新增涂写、折痕或污渍。建议收到后先别让孩子用，确认合适再用。原价128元，我40元出，3折优惠。包顺丰，今天拍今天发。诚信出，期待成交！如需其他教材也可咨询，长期出教材教辅。', '教材,退货,7天,无理由' AS tags, '教材退货政策与使用建议' AS source_summary, 87
  UNION ALL SELECT 'books_textbook', '这套书是真题还是模拟题？年份是哪年的？', '您好！这套是2022年中考真题汇编，包含全国10个省市最新真题，附详细答案解析。真题比模拟题更有参考价值，考点覆盖全面，难度真实。2022年真题对2024年中考仍有很强参考性，核心考点变化不大。原价38元，我15元出，4折优惠。书本9成新，无笔记。包中通，今天拍今天发。如需2023年真题可联系，也有库存。诚信出，期待成交！', '教辅,真题,中考,年份' AS tags, '教辅真题与年份说明' AS source_summary, 88
  UNION ALL SELECT 'books_textbook', '这套书的答案详解详细吗？孩子自学用。', '亲，这套《五年中考三年模拟》答案详解非常详细，每道题都有解题思路和步骤，不只是给答案。适合孩子自学，做完对答案能理解错在哪。答案单独成册，方便核对。书本9成新，答案册全新未翻阅。原价69元，我25元出，3.6折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。诚信出，期待成交，孩子学习有需要随时找我！', '教辅,答案,详解,自学' AS tags, '教辅答案详解与自学适用' AS source_summary, 89
  UNION ALL SELECT 'books_textbook', '这套书有没有书皮？需要包书皮吗？', '您好！这套教材已有透明书皮，发货时附赠2个备用书皮，您收到后可自行更换。书皮能保护封面，延长使用寿命。书本9成新，封面无折痕。原价128元，我40元出（含书皮），3折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。如需其他年级教材也可咨询，长期出教材教辅。诚信出，期待成交！', '教材,书皮,保护,附赠' AS tags, '教材书皮保护与附赠' AS source_summary, 82
  UNION ALL SELECT 'books_textbook', '这套书的练习题难度怎么样？适合什么水平的孩子？', '亲，这套《一遍过》练习题分基础、提升、拓展三个层次，适合中等及以上水平的孩子。基础题巩固课堂知识，提升题训练思维，拓展题拔高能力。如果孩子基础薄弱，建议先用《教材全解》打基础，再用这套巩固。书本9成新，无笔记。原价45元，我15元出，3.3折优惠。包中通，今天拍今天发。有任何学习问题可咨询，期待成交！', '教辅,难度,分层,适用' AS tags, '教辅难度分级与适用水平' AS source_summary, 86
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 2. books_novel - 小说文学 (30 条)
-- ---------------------------------------------------------------------------
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.57', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'books_novel' AS code, '这本《活着》是哪个版本？有没有腰封？' AS question, '您好！这本《活着》是作家出版社2012年版，精装本，原配腰封完好。余华经典作品，印刷清晰，纸张优质。书本9成新，仅书脊有轻微使用痕迹，内页无笔记无折痕。原价28元，我12元出，4.3折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。如需余华其他作品也可咨询，期待成交！' AS answer, '小说,余华,精装,腰封' AS tags, '小说版本与腰封完整性' AS source_summary, 87 AS score
  UNION ALL SELECT 'books_novel', '这本《百年孤独》是范晔翻译版本吗？', '亲，这本《百年孤独》是南海出版公司2011年版，范晔译本，是公认的权威译本。马尔克斯魔幻现实主义代表作，获诺贝尔文学奖。书本9成新，无笔记无折痕，仅扉页有前主人姓名（铅笔可擦）。原价39.5元，我18元出，4.5折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。如需其他外国文学也可咨询，期待成交！', '名著,翻译,范晔,马尔克斯' AS tags, '名著译本确认与品相' AS source_summary, 90
  UNION ALL SELECT 'books_novel', '这套《三体》三部曲是完整套装吗？有没有缺本？', '您好！这套《三体》三部曲完整套装，包括《三体》《三体2黑暗森林》《三体3死神永生》，一本不缺。刘慈欣科幻代表作，获雨果奖。书本9成新，无笔记无折痕，套装一致。原价93元，我35元出，3.8折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。如需刘慈欣其他作品也可咨询，期待成交！', '小说,科幻,三体,套装' AS tags, '小说套装完整性与品相' AS source_summary, 91
  UNION ALL SELECT 'books_novel', '这本《红楼梦》是人民文学出版社版本吗？', '亲，这本《红楼梦》是人民文学出版社2008年版，程乙本，脂砚斋评本，权威版本。上下两册套装，完整无缺。书本9成新，无笔记无折痕，仅书脊有轻微使用痕迹。原价59.7元，我25元出，4.2折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。如需其他四大名著也可咨询，期待成交！', '名著,红楼梦,人文社,套装' AS tags, '名著出版社与版本确认' AS source_summary, 89
  UNION ALL SELECT 'books_novel', '这本小说有没有作者签名？是真迹吗？', '您好！这本《平凡的世界》是路遥签名版，2015年北京十月文艺出版社活动签售，附赠签售海报和购书小票，可证真迹。签名在扉页，钢笔字迹清晰。书本9成新，无笔记无折痕。原价68元，我80元出（签名版溢价），包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。签名版数量有限，收藏价值高，期待成交！', '小说,签名,路遥,收藏' AS tags, '小说签名版真伪与收藏价值' AS source_summary, 93
  UNION ALL SELECT 'books_novel', '这本《围城》有没有笔记或划线？品相怎么样？', '亲，这本《围城》是人民文学出版社版本，9成新，内页无任何笔记、划线或涂画。钱钟书经典作品，印刷清晰，纸张优质。仅扉页有前主人姓名（铅笔可擦），书脊有轻微使用痕迹。原价19元，我8元出，4.2折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。如需钱钟书其他作品也可咨询，期待成交！', '小说,围城,品相,笔记' AS tags, '小说品相与笔记情况' AS source_summary, 85
  UNION ALL SELECT 'books_novel', '这套《金庸全集》是哪个版本？几成新？', '您好！这套是广州出版社朗声旧版《金庸全集》36册，全套齐全不缺本。金庸武侠经典，收藏版。书本8成新，部分册有轻微翻阅痕迹，无笔记无折痕。套装原价680元，我280元出，4.1折优惠。包德邦物流，木架加固发货。7天无理由退换，品相问题包退换。如需金庸单本也可咨询，期待成交！', '小说,金庸,全集,武侠' AS tags, '金庸全集版本与品相' AS source_summary, 92
  UNION ALL SELECT 'books_novel', '这本《白夜行》是哪个译本？东野圭吾的。', '亲，这本《白夜行》是南海出版公司2013年版，李盈春译本，东野圭吾推理经典。书本9成新，无笔记无折痕，仅封面有轻微磨损。原价39.5元，我18元出，4.6折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。如需东野圭吾其他作品也可咨询，我有《解忧杂货店》《嫌疑人X的献身》等库存，期待成交！', '小说,推理,东野圭吾,译本' AS tags, '推理小说译本与品相' AS source_summary, 88
  UNION ALL SELECT 'books_novel', '这套《哈利波特》是中文版还是英文版？' AS question, '您好！这套《哈利波特》中文版7册完整套装，人民文学出版社，马爱农译本。哈利波特魔法经典，适合青少年和成人阅读。书本9成新，无笔记无折痕，套装一致。原价364元，我140元出，3.8折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。如需英文原版也可咨询，期待成交！', '小说,哈利波特,中文版,套装' AS tags, '哈利波特版本与套装' AS source_summary, 90
  UNION ALL SELECT 'books_novel', '这本《追风筝的人》有没有水渍？品相如何？', '亲，这本《追风筝的人》无水渍、无霉斑、无异味。一直存放在干燥书柜中，藏书条件好。书本9成新，无笔记无折痕，仅封面有轻微磨损。原价29元，我12元出，4.1折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。如需胡赛尼其他作品也可咨询，期待成交！', '小说,品相,水渍,追风筝' AS tags, '小说品相与水渍情况' AS source_summary, 84
  UNION ALL SELECT 'books_novel', '这本《挪威的森林》是上海译文出版社版本吗？', '您好！这本《挪威的森林》是上海译文出版社2014年版，林少华译本，村上春树经典作品。书本9成新，无笔记无折痕，仅书脊有轻微使用痕迹。原价29元，我12元出，4.1折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。如需村上春树其他作品也可咨询，期待成交！', '小说,村上春树,译本,品相' AS tags, '小说版本与译本确认' AS source_summary, 86
  UNION ALL SELECT 'books_novel', '这本《小王子》是哪个版本？有插图吗？', '亲，这本《小王子》是人民文学出版社2013年版，马振骋译本，附彩色插图。圣埃克苏佩里经典作品，适合青少年和成人阅读。书本9成新，无笔记无折痕，仅封面有轻微磨损。原价22元，我9元出，4.1折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '小说,小王子,译本,插图' AS tags, '小说版本与插图说明' AS source_summary, 85
  UNION ALL SELECT 'books_novel', '这套网络小说是实体书吗？有删减吗？', '您好！这套是网络小说实体书，正规出版社发行，无删减完整版。我全套齐全不缺本，书本9成新，无笔记无折痕。原价180元，我70元出，3.9折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。网络小说实体书比手机看舒服，期待成交！', '网络小说,实体书,完整,无删减' AS tags, '网络小说实体书与完整性' AS source_summary, 83
  UNION ALL SELECT 'books_novel', '这本《解忧杂货店》是哪个版本？有腰封吗？', '亲，这本《解忧杂货店》是南海出版公司2014年版，李盈春译本，东野圭吾暖心作品。原配腰封完好，书本9成新，无笔记无折痕。原价39.5元，我18元出，4.6折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。如需东野圭吾其他作品也可咨询，期待成交！', '小说,解忧,腰封,品相' AS tags, '小说版本与腰封说明' AS source_summary, 86
  UNION ALL SELECT 'books_novel', '这套《明朝那些事儿》是完整套装吗？几本？' AS question, '您好！这套《明朝那些事儿》是当年明月著，北京联合出版社2014年版，全套9册完整套装。书本9成新，无笔记无折痕，套装一致。原价358元，我130元出，3.6折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。明朝历史通俗读物，期待成交！', '小说,明朝,套装,完整' AS tags, '明朝那些事儿套装完整性' AS source_summary, 89
  UNION ALL SELECT 'books_novel', '这本《平凡的世界》是哪个版本？有几册？', '亲，这套《平凡的世界》是北京十月文艺出版社2017年版，路遥著，全套3册。书本9成新，无笔记无折痕，套装一致。原价138元，我50元出，3.6折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。茅盾文学奖作品，期待成交！', '小说,平凡的世界,套装,路遥' AS tags, '平凡的世界版本与套装' AS source_summary, 87
  UNION ALL SELECT 'books_novel', '这本《了不起的盖茨比》是哪个译本？' AS question, '您好！这本《了不起的盖茨比》是上海译文出版社2018年版，巫宁坤译本，菲茨杰拉德经典作品。书本9成新，无笔记无折痕，仅书脊有轻微使用痕迹。原价28元，我12元出，4.3折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。如需其他美国文学也可咨询，期待成交！', '小说,盖茨比,译本,品相' AS tags, '小说译本与品相说明' AS source_summary, 84
  UNION ALL SELECT 'books_novel', '这本诗集是精装还是平装？有书签吗？', '亲，这本《海子诗全集》是精装本，附赠书签。海子经典诗集，收藏版。书本9成新，无笔记无折痕，精装封面完好。原价68元，我35元出，5.1折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。精装本适合收藏和送礼，期待成交！', '诗集,海子,精装,书签' AS tags, '诗集装帧与赠品说明' AS source_summary, 86
  UNION ALL SELECT 'books_novel', '这本《围城》能再便宜点吗？诚心要的。', '亲，这本《围城》原价19元，我8元出已经很便宜了，4.2折。如果您诚心要，6元包邮给您，这是底价了。书本9成新，无笔记无折痕。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。如需钱钟书其他作品可一并出，再优惠2元。诚信出，期待成交！', '小说,议价,围城,优惠' AS tags, '小说议价与优惠说明' AS source_summary, 80
  UNION ALL SELECT 'books_novel', '这套《余华全集》有几本？是正版吗？', '您好！这套余华作品集共6本，包括《活着》《许三观卖血记》《兄弟》《在细雨中呼喊》《第七天》《温润》。作家出版社正版，有购买记录可查。书本9成新，无笔记无折痕。原价180元，我70元出，3.9折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '小说,余华,全集,正版' AS tags, '余华作品集完整性与正版' AS source_summary, 88
  UNION ALL SELECT 'books_novel', '这本《白鹿原》是哪个版本？有删减吗？', '亲，这本《白鹿原》是人民文学出版社2012年版，陈忠实著，无删减完整版，茅盾文学奖作品。书本9成新，无笔记无折痕，仅书脊有轻微使用痕迹。原价58元，我25元出，4.3折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '小说,白鹿原,版本,无删减' AS tags, '白鹿原版本与完整性说明' AS source_summary, 87
  UNION ALL SELECT 'books_novel', '这本散文集是哪个作者的？品相怎么样？', '您好！这本《文化苦旅》是余秋雨著，长江文艺出版社2014年版。余秋雨文化散文经典，文笔优美。书本9成新，无笔记无折痕，仅封面有轻微磨损。原价38元，我15元出，3.9折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。如需余秋雨其他作品也可咨询，期待成交！', '散文,余秋雨,品相,版本' AS tags, '散文集版本与品相说明' AS source_summary, 85
  UNION ALL SELECT 'books_novel', '这套《张爱玲全集》是哪个出版社的？', '亲，这套《张爱玲全集》是北京十月文艺出版社2012年版，全套18册完整套装。张爱玲经典作品集，文学价值高。书本9成新，无笔记无折痕，套装一致。原价360元，我140元出，3.9折优惠。包德邦物流，木架加固发货。7天无理由退换，品相问题包退换。期待成交！', '小说,张爱玲,全集,套装' AS tags, '张爱玲全集版本与套装' AS source_summary, 90
  UNION ALL SELECT 'books_novel', '这本《浮生六记》是哪个译本？有注释吗？', '您好！这本《浮生六记》是上海古籍出版社2016年版，沈复著，有详细注释和白话翻译。清代文学经典，文笔清新。书本9成新，无笔记无折痕，仅封面有轻微磨损。原价25元，我10元出，4折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '散文,浮生六记,注释,版本' AS tags, '浮生六记版本与注释说明' AS source_summary, 83
  UNION ALL SELECT 'books_novel', '这套小说能打包收吗？有优惠吗？', '亲，这套小说共5本：《活着》《百年孤独》《三体》《白夜行》《解忧杂货店》，单买总价85元。如果您打包一起收，给您优惠价70元包邮，相当于8.2折。书本都是9成新，品质很好。打包出对我也省心，对您也划算。诚心要的话65元给您，再送一个书签。', '小说,打包,优惠,套装' AS tags, '小说打包优惠与议价说明' AS source_summary, 85
  UNION ALL SELECT 'books_novel', '这本《许三观卖血记》有笔记吗？品相如何？', '亲，这本《许三观卖血记》是作家出版社2012年版，余华著，9成新。内页无任何笔记、划线或涂画。仅扉页有前主人姓名（铅笔可擦），书脊有轻微使用痕迹。原价29元，我12元出，4.1折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '小说,许三观,品相,笔记' AS tags, '小说品相与笔记情况' AS source_summary, 84
  UNION ALL SELECT 'books_novel', '这套《读者文摘》合集是哪年的？有收藏价值吗？', '您好！这套《读者文摘》合集是2015-2018年精选4册，收录经典文章。书本9成新，无笔记无折痕，套装一致。原价120元，我45元出，3.8折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。文章经典，适合收藏和阅读，期待成交！', '文学,读者,合集,收藏' AS tags, '读者文摘合集与收藏价值' AS source_summary, 82
  UNION ALL SELECT 'books_novel', '这本《人间失格》是哪个译本？太宰治的。', '亲，这本《人间失格》是作家出版社2018年版，李盈春译本，太宰治日本文学经典。书本9成新，无笔记无折痕，仅封面有轻微磨损。原价25元，我10元出，4折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。如需太宰治其他作品也可咨询，期待成交！', '小说,太宰治,译本,品相' AS tags, '小说译本与品相说明' AS source_summary, 85
  UNION ALL SELECT 'books_novel', '这本小说的ISBN能发一下吗？我想查证。', '您好！这本《活着》的ISBN是978-7-5063-6587-2，作家出版社2012年版。您可以通过ISBN在出版社官网或京东图书查证。书本9成新，无笔记无折痕。原价28元，我12元出，4.3折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。诚信出，期待成交！', '小说,ISBN,查证,正版' AS tags, '小说ISBN与正版验证' AS source_summary, 88
  UNION ALL SELECT 'books_novel', '这本《活着》适合多大年纪的人看？内容会不会太沉重？', '亲，这本《活着》适合15岁以上读者，初中高中生和成年人都适合。余华的文笔朴实却震撼，虽然写的是苦难但内核是生命的坚韧，不算刻意煽情。如果是给孩子看，建议初二以上阅读理解能力够了再看。这本书是当代文学经典，北大清华都列为必读书目，文学价值很高。书本9成新，无笔记无折痕，原价28元我12元出。包圆通，今天拍今天发，期待成交！', '小说,年龄,活着,余华,阅读' AS tags, '小说适读年龄与内容评价' AS source_summary, 86
) q
