INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.57', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'books_magazine' AS code, '这批《读者》杂志是哪年哪期的？完整吗？' AS question, '您好！这批《读者》杂志是2022年全年24期完整合订，一本不缺。杂志保存很好，无缺页无涂画，仅封面有轻微磨损。读者杂志文章经典，适合阅读和收藏。原价120元（全年），我40元出，3.3折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！' AS answer, '杂志,读者,合订,完整' AS tags, '读者杂志期号与完整性说明' AS source_summary, 86 AS score
  UNION ALL SELECT 'books_magazine', '这套《意林》是合订本还是单期？有几本？', '亲，这套《意林》是2023年合订本，共4本（春夏秋冬各1本）。合订本比单期更方便阅读和保存，文章精选。杂志9成新，无笔记无折痕，套装一致。原价120元，我45元出，3.8折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '杂志,意林,合订本,套装' AS tags, '意林合订本与套装说明' AS source_summary, 84
  UNION ALL SELECT 'books_magazine', '这本《国家地理》是中文版还是英文版？' AS question, '您好！这本《国家地理》是中文版，2012年某期，摄影精美，内容权威。杂志9成新，无缺页无涂画，仅封面有轻微磨损。原价20元，我8元出，4折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。如需其他期号也可咨询，期待成交！', '杂志,国家地理,中文版,摄影' AS tags, '国家地理版本与品相说明' AS source_summary, 87
  UNION ALL SELECT 'books_magazine', '这批《时尚》杂志是哪年的？有海报吗？', '亲，这批《时尚》杂志是2021年6本（双月刊），部分期附赠海报。杂志9成新，无缺页无涂画，仅封面有轻微磨损。原价180元（全年），我60元出，3.3折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。时尚杂志适合翻阅和收藏，期待成交！', '杂志,时尚,海报,年份' AS tags, '时尚杂志年份与海报说明' AS source_summary, 83
  UNION ALL SELECT 'books_magazine', '这套《读者》能再便宜点吗？诚心收的。', '亲，这批《读者》全年24期原价120元，我40元出已经很便宜了，3.3折。如果您诚心要，35元包邮给您，这是底价了。杂志保存很好，无缺页无涂画。包中通，今天拍今天发。7天无理由退换，品相问题包退换。诚信出，期待成交！', '杂志,读者,议价,优惠' AS tags, '读者杂志议价与优惠说明' AS source_summary, 82
  UNION ALL SELECT 'books_magazine', '这本《看天下》是哪期的？内容过时吗？', '您好！这本《Vista看天下》是2023年第18期，内容是时事评论和文化随笔，不会过时。杂志9成新，无缺页无涂画，仅封面有轻微磨损。原价15元，我5元出，3.3折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '杂志,看天下,期号,时事' AS tags, '看天下杂志期号与内容' AS source_summary, 81
  UNION ALL SELECT 'books_magazine', '这套《三联生活周刊》是全年合订吗？' AS question, '亲，这套《三联生活周刊》是2022年全年52期完整合订，一本不缺。杂志保存很好，无缺页无涂画，仅部分封面有轻微磨损。原价260元（全年），我90元出，3.5折优惠。包德邦物流，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '杂志,三联,合订,全年' AS tags, '三联生活周刊全年合订说明' AS source_summary, 85
