  UNION ALL SELECT 'books_magazine', '这本《南方人物周刊》是哪期的？有删页吗？', '亲，这本《南方人物周刊》是2023年第15期，无删页无缺页，完整保存。杂志9成新，无涂画无折痕，仅封面有轻微磨损。原价15元，我5元出，3.3折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '杂志,南方人物,期号,完整' AS tags, '南方人物周刊期号与完整性' AS source_summary, 82
  UNION ALL SELECT 'books_magazine', '这套《故事会》是合订本吗？有几本？', '您好！这套《故事会》是2021年合订本，共4本（春夏秋冬各1本）。合订本比单期更方便阅读和保存。杂志9成新，无缺页无涂画，套装一致。原价80元，我30元出，3.8折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '杂志,故事会,合订本,套装' AS tags, '故事会合订本与套装说明' AS source_summary, 80
  UNION ALL SELECT 'books_magazine', '这本《知音》是哪期的？品相怎么样？', '亲，这本《知音》是2023年第8期，9成新。无缺页无涂画，仅封面有轻微磨损。原价10元，我3元出，3折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。如需其他期号也可咨询，期待成交！', '杂志,知音,期号,品相' AS tags, '知音杂志期号与品相说明' AS source_summary, 79
  UNION ALL SELECT 'books_magazine', '这套《中国国家地理》是哪年的？有地图附赠吗？', '您好！这套《中国国家地理》是2022年全年12期完整合订，部分期附赠地图。杂志保存很好，无缺页无涂画，摄影精美。原价240元（全年），我80元出，3.3折优惠。包德邦物流，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '杂志,国家地理,全年,地图' AS tags, '国家地理全年合订与地图附赠' AS source_summary, 88
  UNION ALL SELECT 'books_magazine', '这批杂志支持同城自提吗？我在上海。', '亲，我在上海浦东，支持同城自提，地点可约世纪公园地铁站附近。自提可再优惠5元，因为省了邮费。杂志可当面验货，满意再付款。如需邮寄也可，包中通，今天发2-3天到。7天无理由退换（自提取货后不支持退货，邮寄支持）。诚信出，期待成交！', '杂志,同城,自提,上海' AS tags, '杂志同城自提与优惠' AS source_summary, 81
  UNION ALL SELECT 'books_magazine', '这套《博客天下》是哪年的？过时吗？', '您好！这套《博客天下》是2022年合订本，内容是时事评论和文化随笔，不会过时。杂志9成新，无缺页无涂画，套装一致。原价120元，我40元出，3.3折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '杂志,博客天下,年份,时事' AS tags, '博客天下杂志年份与内容' AS source_summary, 80
  UNION ALL SELECT 'books_magazine', '这本《人物》杂志有签名专访吗？' AS question, '亲，这本《人物》杂志是2023年第10期，有某知名作家专访，无签名。杂志9成新，无缺页无涂画，仅封面有轻微磨损。原价20元，我8元出，4折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '杂志,人物,专访,期号' AS tags, '人物杂志专访与期号说明' AS source_summary, 81
  UNION ALL SELECT 'books_magazine', '这套《新周刊》是合订本吗？几本？', '您好！这套《新周刊》是2022年合订本，共6本（双月合订）。杂志9成新，无缺页无涂画，套装一致。原价180元，我60元出，3.3折优惠。包中通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '杂志,新周刊,合订本,套装' AS tags, '新周刊合订本与套装说明' AS source_summary, 82
  UNION ALL SELECT 'books_magazine', '这批杂志什么时候发货？多久能到？', '亲，今天下午4点前拍下，当天下午5点发中通，2-3天到；4点后拍下，次日上午发，3-4天到。偏远地区需加5元邮费。发货前会拍照确认品相，发货后会提供运单号。如收到有品相问题，7天内包退换，邮费我承担。诚信出，期待成交！', '杂志,发货,物流,时效' AS tags, '杂志发货时效与物流查询' AS source_summary, 83
  UNION ALL SELECT 'books_magazine', '这套《财经》杂志是哪年的？有收藏价值吗？', '亲，这套《财经》杂志是2022年全年24期完整合订，内容是财经评论和分析，有参考价值。杂志9成新，无缺页无涂画，套装一致。原价480元（全年），我160元出，3.3折优惠。包德邦物流，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '杂志,财经,全年,收藏' AS tags, '财经杂志全年合订与收藏' AS source_summary, 86
  UNION ALL SELECT 'books_magazine', '这本《时尚芭莎》有附赠小样吗？' AS question, '您好！这本《时尚芭莎》是2023年第6期，部分附赠化妆品小样（已用完）。杂志9成新，无缺页无涂画，仅封面有轻微磨损。原价20元，我8元出，4折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '杂志,时尚芭莎,小样,期号' AS tags, '时尚芭莎小样与期号说明' AS source_summary, 80
  UNION ALL SELECT 'books_magazine', '这套《读者》能拆卖吗？我只要上半年。', '亲，建议您整年收下，拆卖后剩余不好出。不过如果您只要上半年12期，我可以拆，价格25元（全年40元）。但下半年会再等买家，可能要一段时间。如果您急用，建议整年收，下半年可转赠朋友。整年出性价比更高。包中通，今天拍今天发。7天无理由退换，放心拍！', '杂志,读者,拆卖,半年' AS tags, '读者杂志拆卖建议与价格' AS source_summary, 79
