INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.57', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'books_professional' AS code, '这本《JavaScript高级程序设计》是第几版？最新吗？' AS question, '您好！这本是《JavaScript高级程序设计》第4版，2022年人民邮电出版社出版，是最新版。涵盖ES6到ES10新特性，前端开发必备参考书。书本9成新，无笔记无折痕，仅书脊有轻微使用痕迹。原价129元，我60元出，4.7折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！' AS answer, '编程,JS,第4版,最新' AS tags, '编程书籍版本与最新性说明' AS source_summary, 90 AS score
  UNION ALL SELECT 'books_professional', '这本《算法导论》是中文版还是英文版？', '亲，这本是《算法导论》中文版第3版，机械工业出版社2013年版。算法领域权威教材，MIT经典课程用书。书本9成新，无笔记无折痕，仅书脊有轻微使用痕迹。原价128元，我60元出，4.7折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '编程,算法,中文版,权威' AS tags, '算法导论版本与语言说明' AS source_summary, 92
  UNION ALL SELECT 'books_professional', '这本《深入理解计算机系统》是第几版？', '您好！这本是《深入理解计算机系统》第3版，2016年机械工业出版社出版。计算机系统经典教材，CMU课程用书。书本9成新，无笔记无折痕，仅书脊有轻微使用痕迹。原价139元，我65元出，4.7折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '编程,CSAPP,第3版,经典' AS tags, 'CSAPP版本与教材说明' AS source_summary, 91
  UNION ALL SELECT 'books_professional', '这本《内科学》是第几版？最新吗？', '亲，这本是《内科学》第9版，人民卫生出版社2018年版。医学权威教材，全国高等医药院校统编教材。书本9成新，无笔记无折痕，仅书脊有轻微使用痕迹。原价99元，我45元出，4.5折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '医学,内科学,第9版,教材' AS tags, '医学教材版本与权威性' AS source_summary, 89
  UNION ALL SELECT 'books_professional', '这本《民法典》是最新版吗？有注释吗？', '您好！这本是《中华人民共和国民法典》2021年版，法律出版社，含条文释义和案例解读。民法典是最新颁布的法律，2021年1月1日实施。书本9成新，无笔记无折痕，仅封面有轻微磨损。原价58元，我25元出，4.3折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '法律,民法典,最新,注释' AS tags, '民法典版本与注释说明' AS source_summary, 88
  UNION ALL SELECT 'books_professional', '这本《经济学原理》是曼昆版吗？第几版？', '亲，这本是曼昆《经济学原理》第8版，北京大学出版社2020年版。经济学经典教材，哈佛大学课程用书。书本9成新，无笔记无折痕，仅书脊有轻微使用痕迹。原价128元，我60元出，4.7折优惠。包顺丰，今天拍今天发。7天无理由退换，品相问题包退换。期待成交！', '经管,经济学,曼昆,第8版' AS tags, '经济学教材版本与作者' AS source_summary, 90
