)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.57', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'books_children' AS code, '这套绘本适合几岁孩子？内容难度怎么样？' AS question, '您好！这套《好饿的毛毛虫》适合2-5岁孩子，内容简单有趣，图画精美。绘本是儿童启蒙经典，帮助孩子认知颜色、食物和星期概念。书本9成新，无涂画无折痕，仅封面有轻微磨损。原价39.8元，我15元出，3.8折优惠。包圆通，今天拍今天发。7天无理由退换，品相问题包退换。如需其他绘本也可咨询，期待成交！' AS answer, '绘本,年龄,启蒙,毛毛虫' AS tags, '绘本适用年龄与内容说明' AS source_summary, 88 AS score
